#[path = "../algebraic.rs"]
mod algebraic;
#[path = "../ordering.rs"]
mod ordering;
#[path = "../pointwise.rs"]
mod pointwise;
#[path = "../vector_clock.rs"]
mod vector_clock;
#[path = "../causal_order.rs"]
mod causal_order;

fn main() {
    let local = vec![2, 3, 1];
    let message = vec![1, 4, 1];
    let ready = causal_order::is_causally_ready(&message, &local, 1);
    let raw_happens_before = vector_clock::happens_before(&local, &message);
    let merged = vector_clock::merge(&local, &message);
    let merged_happens_before = vector_clock::happens_before(&local, &merged);
    let exhausted_sender_ready = causal_order::is_causally_ready(&vec![0], &vec![u64::MAX], 0);
    assert!(ready);
    assert!(!raw_happens_before);
    assert_eq!(merged, vec![2, 4, 1]);
    assert!(merged_happens_before);
    assert!(!exhausted_sender_ready);
    println!("{{\"causally_ready\":{ready},\"raw_happens_before\":{raw_happens_before},\"merged\":{merged:?},\"merged_happens_before\":{merged_happens_before},\"exhausted_sender_ready\":{exhausted_sender_ready}}}");
}
